  topics: [
    { t: '部首が意味を教えてくれる', lead: '読めない漢字に出会ったとき、手がかりになるのが部首である。2級の配当漢字は、部首と意味の対応がとくに素直なものが多い。',
      body: [
        '手へんの字を並べてみる。拭く、捉える、拉く、捻る、捗る、拳、挫く。どれも手を使う動作か、手の形そのものである。偏が意味の領域を決め、つくりが音を決める。漢字の多くはこの形声の仕組みでできている。',
        'たとえば捗の音はチョクだが、これは右側の「歩」に近い部分から来ている。意味は手へんが担い、「手で物事を進める」から「はかどる」になった。音と意味が別々の部品に分かれている。',
        'この仕組みが分かると、初めて見る字でもおおよその見当がつく。腺という字は、にくづきに泉。体の中で液を出すところ、と推測できる。実際そのとおりである。',
        'ただし例外もある。斬は手を使う動作だが部首は斤、おのである。刃物で断つ意味が強いためだ。采の部首は釆（のごめへん）で、米ではない。部首を問う問題は、こうした例外を狙ってくる。',
        'つまり部首は、たいていの場合は意味の手がかりになり、ときどき裏切る。裏切る字をいくつか覚えておけば、あとは素直に推測してよい。',
        '覚える順序としては、まず素直な字でしくみを体に入れ、そのあとで例外を潰していく。この順でやると、185字が部首ごとのまとまりとして頭に入る。',
      ]},
  ],
