        '理由は、情報機器の普及である。文章の多くがキーボードで入力されるようになり、変換して選ぶだけで難しい字が書けるようになった。手で書く機会が減った分、読む機会は増えた。',
        '憂鬱という語を考えてみる。「憂うつ」と交ぜ書きすれば書きやすいが、語としてのまとまりは崩れる。読めるのなら、まるごと漢字で書いたほうが意味が取りやすい。',
